  `deletedAt` datetime(3) DEFAULT NULL,
  `createdBy` varchar(191) DEFAULT NULL,
  `updatedBy` varchar(191) DEFAULT NULL,
  `nomeNormalizado` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `municipios_codigoIbge_key` (`codigoIbge`),
  KEY `municipios_uf_nomeNormalizado_idx` (`uf`,`nomeNormalizado`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
