--
-- Table structure for table `pnae_chamadas_publicas`
--

DROP TABLE IF EXISTS `pnae_chamadas_publicas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pnae_chamadas_publicas` (
  `id` varchar(191) NOT NULL,
  `editalId` varchar(191) NOT NULL,
  `numero` varchar(191) NOT NULL,
  `exercicio` int(11) NOT NULL,
  `objeto` text NOT NULL,
  `entidadeExecutoraId` varchar(191) DEFAULT NULL,
  `dreId` varchar(191) DEFAULT NULL,
  `municipioId` varchar(191) DEFAULT NULL,
  `inscricoesInicio` datetime(3) NOT NULL,
  `inscricoesFim` datetime(3) NOT NULL,
  `dataAbertura` datetime(3) DEFAULT NULL,
  `prazoDocumentos` datetime(3) DEFAULT NULL,
  `localApresentacao` varchar(191) DEFAULT NULL,
  `formaApresentacao` varchar(191) DEFAULT NULL,
  `status` enum('RASCUNHO','PUBLICADA','INSCRICOES_ABERTAS','INSCRICOES_ENCERRADAS','EM_HABILITACAO','EM_SELECAO','RESULTADO_PRELIMINAR','EM_RECURSO','HOMOLOGADA','CANCELADA') NOT NULL DEFAULT 'RASCUNHO',
  `versaoPublicada` int(11) NOT NULL DEFAULT 1,
  `publicadaEm` datetime(3) DEFAULT NULL,
  `responsavelId` varchar(191) DEFAULT NULL,
  `observacoes` text DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `createdBy` varchar(191) DEFAULT NULL,
  `updatedBy` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pnae_chamadas_publicas_dreId_numero_exercicio_key` (`dreId`,`numero`,`exercicio`),
  KEY `pnae_chamadas_publicas_editalId_idx` (`editalId`),
  KEY `pnae_chamadas_publicas_dreId_municipioId_idx` (`dreId`,`municipioId`),
  KEY `pnae_chamadas_publicas_status_inscricoesFim_idx` (`status`,`inscricoesFim`),
  KEY `pnae_chamadas_publicas_entidadeExecutoraId_fkey` (`entidadeExecutoraId`),
  KEY `pnae_chamadas_publicas_municipioId_fkey` (`municipioId`),
  CONSTRAINT `pnae_chamadas_publicas_dreId_fkey` FOREIGN KEY (`dreId`) REFERENCES `dres` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `pnae_chamadas_publicas_editalId_fkey` FOREIGN KEY (`editalId`) REFERENCES `pnae_editais` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `pnae_chamadas_publicas_entidadeExecutoraId_fkey` FOREIGN KEY (`entidadeExecutoraId`) REFERENCES `entidades_executoras` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `pnae_chamadas_publicas_municipioId_fkey` FOREIGN KEY (`municipioId`) REFERENCES `municipios` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

