INSERT INTO `pnae_edital_itens` VALUES ('045057d2-c487-453e-a14c-40d318e8bda9','7f06e3da-75b8-4768-afbd-25ddd56144fb','FARINHA DE MANDIOCA','FARINHA DE MANDIOCA, do tipo branca ou amarela, torrada, grupo seco, subgrupo média, classe branca, isenta de matéria terrosa, fungos ou parasitas, umidade e fragmentos estranhos. As características deverão atender aos requisitos mínimos de identidade e qualidade estabelecidos na legislação vigente. Embalagem de polietileno atóxico, resistente podendo ser transparente ou de papel Kraft branco/cores de 1Kg, contendo externamente os dados de identificação do fabricante, informações nutricionais, número de lote, data de fabricação, data de validade, quantidade do produto. No ato da entrega o prazo restante de validade deverá ser igual ou superior à metade do período entre a sua data de fabricação e sua data final de validade.',1318.00,'KG',NULL,NULL,NULL,'IMPORTADO',0,'2026-10-09 00:11:36.546','2026-10-09 00:11:36.546',NULL,'importador-editais',NULL,1,53,'do tipo branca ou amarela, torrada, grupo seco, subgrupo média, classe branca, isenta de matéria terrosa, fungos ou parasitas, umidade e fragmentos estranhos. As características deverão atender aos requisitos mínimos de identidade e qualidade estabelecidos na legislação vigente. Embalagem de polietileno atóxico,'),('04724224-0b4a-40f8-b116-25698bb6d08b','24f2257e-d350-48ea-92e7-39decb6e2698','PIMENTÃO VERDE','PIMENTÃO VERDE, verde, inteiro, livre de sujidades, insetos, apresentando desenvolvimento completo, isento de odores estranhos e deformidades, isento de podridões, não se apresentar desidratado, murcho ou congelado. As características deverão atender aos requisitos mínimos de identidade e qualidade estabelecidos na legislação vigente. Acondicionada em saco plástico atóxico, transparente e resistente.',83.00,'KG',12.29,1020.07,NULL,'IMPORTADO',0,'2026-10-09 00:11:38.195','2026-10-09 00:11:38.195',NULL,'importador-editais',NULL,1,45,'verde, inteiro, livre de sujidades, insetos