DROP TABLE IF EXISTS `pnae_programacao_entrega_itens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pnae_programacao_entrega_itens` (
  `id` varchar(191) NOT NULL,
  `programacaoId` varchar(191) NOT NULL,
  `contratoItemId` varchar(191) NOT NULL,
  `produto` varchar(191) NOT NULL,
  `unidadeMedida` varchar(191) DEFAULT NULL,
  `quantidadeProgramada` decimal(14,4) NOT NULL,
  `valorUnitarioContratual` decimal(14,4) NOT NULL,
  `valorTotalPrevisto` decimal(14,2) NOT NULL,
  `quantidadeReservada` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `deletedAt` datetime(3) DEFAULT NULL,
  `createdBy` varchar(191) DEFAULT NULL,
  `updatedBy` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pnae_programacao_entrega_itens_programacaoId_idx` (`programacaoId`),
  KEY `pnae_programacao_entrega_itens_contratoItemId_idx` (`contratoItemId`),
  CONSTRAINT `pnae_programacao_entrega_itens_contratoItemId_fkey` FOREIGN KEY (`contratoItemId`) REFERENCES `pnae_contrato_itens` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `pnae_programacao_entrega_itens_programacaoId_fkey` FOREIGN KEY (`programacaoId`) REFERENCES `pnae_programacoes_entrega` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

